@@ -119,6 +119,57 @@ export const updateWebhookAction = authenticatedActionClient.inputSchema(ZUpdate
   })
 );

+const ZDuplicateWebhookAction = z.object({
+  webhookId: ZId,
+});
+
+export const duplicateWebhookAction = authenticatedActionClient
+  .inputSchema(ZDuplicateWebhookAction)
+  .action(async ({ ctx, parsedInput }) => {
+    const webhookId = parsedInput.webhookId;
+    const organizationId = await getOrganizationIdFromWebhookId(webhookId);
+    const webhookResult = await getWebhook(webhookId);
+
+    if (!webhookResult.ok) {
+      throw new ResourceNotFoundError("Webhook", webhookId);
+    }
+
+    const existing = webhookResult.data;
+
+    const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);
+    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
+      type: "workspace",
+      id: workspaceId,
+    });
+    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);
+    await assertNewlyAttachedSurveysWorkspaceVisible(existing.surveyIds);
+
+    const newWebhook = await createWebhook(workspaceId, {
+      name: `Copy of ${existing.name ?? "Webhook"}`,
+      url: existing.url,
+      source: existing.source,
+      triggers: existing.triggers,
+      surveyIds: existing.surveyIds,
+    });
+
+    ctx.auditLoggingCtx.organizationId = organizationId;
+    ctx.auditLoggingCtx.webhookId = webhookId;
+    ctx.auditLoggingCtx.newObject = newWebhook;
+
+    capturePostHogEvent(
+      ctx.user.id,
+      "integration_connected",
+      {
+        integration_type: "webhook",
+        organization_id: organizationId,
+        workspace_id: workspaceId,
+      },
+      { organizationId, workspaceId }
+    );
+
+    return newWebhook;
+  });
+
