/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — clone a webhook into a new one.
 *
 * Reads the source webhook, asserts workspace.write authorization, and creates a copy with
 * "Copy of <name>" as the default name.
 */
import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { assertCan } from "@/lib/authorization";
import { capturePostHogEvent } from "@/lib/posthog";
import { assertNewlyAttachedSurveysWorkspaceVisible } from "@/lib/survey/visibility/outbound";
import { getOrganizationIdFromWebhookId, getWorkspaceIdFromWebhookId } from "@/lib/utils/helper";
import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { problemNotFound, successResponse } from "@/app/api/v3/lib/response";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "webhook",
  schemas: { params: z.object({ webhookId: ZId }).strict() },
  handler: async ({ req, parsedInput, authentication, auditLog, requestId, instance }) => {
    const webhookId = parsedInput.params.webhookId;
    const organizationId = await getOrganizationIdFromWebhookId(webhookId);
    const webhookResult = await getWebhook(webhookId);

    if (!webhookResult.ok) {
      return problemNotFound(requestId, "Webhook", webhookId, instance);
    }

    const existing = webhookResult.data;

    const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);
    await assertCan({ type: "user", id: authentication.userId }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);
    await assertNewlyAttachedSurveysWorkspaceVisible(existing.surveyIds);

    const newWebhook = await createWebhook(workspaceId, {
      name: `Copy of ${existing.name ?? "Webhook"}`,
      url: existing.url,
      source: existing.source,
      triggers: existing.triggers,
      surveyIds: existing.surveyIds,
    });

    auditLog!.objectType = "webhook";
    auditLog!.objectId = newWebhook.id;
    auditLog!.objectName = newWebhook.name ?? undefined;
    auditLog!.organizationId = organizationId;
    auditLog!.workspaceId = workspaceId;

    capturePostHogEvent(
      authentication.userId,
      "integration_connected",
      {
        integration_type: "webhook",
        organization_id: organizationId,
        workspace_id: workspaceId,
      },
      { organizationId, workspaceId }
    );

    return successResponse(newWebhook, { requestId });
  },
});

import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import { Webhook } from "@formbricks/database/prisma";

/**
 * Client fetchers for the internal webhook management routes.
 */

const BASE_PATH = "/api/v3/webhooks";
const MUTATION_TIMEOUT_MS = 15_000;

/**
 * Duplicate (clone) a webhook. The new webhook gets the name "Copy of <original name>".
 *
 * Resolves with the newly created webhook on success; throws a parsed `V3ApiError` on a
 * non-2xx response.
 */
export async function duplicateWebhook(webhookId: string): Promise<Webhook> {
  const response = await fetch(`${BASE_PATH}/${encodeURIComponent(webhookId)}/duplicate`, {
    method: "POST",
    signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  return ((await response.json()) as { data: Webhook }).data;
}

import type { Webhook } from "@formbricks/database/prisma-browser";

/**
 * Typed query-key factory for webhook-related queries.
 */
export const webhookKeys = {
  all: ["webhooks"] as const,
  lists: () => [...webhookKeys.all, "list"] as const,
  list: (workspaceId: string) => [...webhookKeys.lists(), workspaceId] as const,
  webhook: (webhookId: string) => [...webhookKeys.all, webhookId] as const,
  /** Infer the result type of a query so the caller never has to type `data` manually. */
  webhookType: () => null as unknown as Webhook,
};

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { duplicateWebhook } from "@/modules/integrations/webhooks/lib/api-client";
import { webhookKeys } from "@/modules/integrations/webhooks/lib/query";

/**
 * Hook that duplicates a webhook via the v3 API.
 *
 * On success, invalidates the workspace's webhook list so the table refreshes with the new row.
 */
export const useDuplicateWebhook = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (webhookId: string) => duplicateWebhook(webhookId),
    onSuccess: (_data, webhookId) => {
      // Invalidate all workspace-scoped webhook lists so the table picks up the new row.
      queryClient.invalidateQueries({ queryKey: webhookKeys.lists() });
    },
  });
};

"use client";

import { TFunction } from "i18next";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { timeSince } from "@/lib/time";
import { RestrictedSurveyHint } from "@/modules/survey/visibility/components/restricted-survey-hint";
import { hasRestrictedAttachedSurvey } from "@/modules/survey/visibility/lib/outbound";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";
import { CopyIcon } from "lucide-react";
import { toast } from "react-hot-toast";
import { useDuplicateWebhook } from "@/modules/integrations/webhooks/hooks/use-duplicate-webhook";
import { getV3ApiErrorMessage } from "@/modules/api/lib/v3-client";

const renderSelectedSurveysText = (webhook: Webhook, allSurveys: TSurvey[]) => {
  let surveyNames: string[];

  if (webhook.surveyIds.length === 0) {
    surveyNames = allSurveys.map((survey) => survey.name);
  } else {
    surveyNames = webhook.surveyIds
      .map((surveyId) => {
        const survey = allSurveys.find((s) => s.id === surveyId);
        return survey ? survey.name : "";
      })
      .filter(Boolean);
  }

  if (surveyNames.length === 0) {
    return <p className="text-slate-400">-</p>;
  }

  return (
    <p className="truncate text-slate-400" title={surveyNames.join(", ")}>
      {surveyNames.join(", ")}
    </p>
  );
};

const renderSelectedTriggersText = (webhook: Webhook, t: TFunction) => {
  if (webhook.triggers.length === 0) {
    return <p className="text-slate-400">{t("workspace.integrations.webhooks.no_triggers")}</p>;
  } else {
    let cleanedTriggers = webhook.triggers.map((trigger) => {
      if (trigger === "responseCreated") {
        return t("workspace.integrations.webhooks.response_created");
      } else if (trigger === "responseUpdated") {
        return t("workspace.integrations.webhooks.response_updated");
      } else if (trigger === "responseFinished") {
        return t("workspace.integrations.webhooks.response_finished");
      } else {
        return trigger;
      }
    });

    return (
      <p className="text-slate-400">
        {cleanedTriggers
          .sort((a, b) => {
            const triggerOrder = {
              "Response Created": 1,
              "Response Updated": 2,
              "Response Finished": 3,
            };

            return (triggerOrder as Record<string, number>)[a] - (triggerOrder as Record<string, number>)[b];
          })
          .join(", ")}
      </p>
    );
  }
};

export const WebhookRowData = ({
  webhook,
  surveys,
  surveyVisibilityEnabled,
}: Readonly<{ webhook: Webhook; surveys: TSurvey[]; surveyVisibilityEnabled: boolean }>) => {
  const { t, i18n } = useTranslation();
  const locale = i18n.resolvedLanguage ?? i18n.language ?? "en-US";
  const { mutate: duplicate, isPending } = useDuplicateWebhook();

  const handleDuplicate = () => {
    duplicate(webhook.id, {
      onSuccess: () => {
        toast.success(t("workspace.integrations.webhooks.webhook_duplicated_successfully"));
      },
      onError: (_err) => {
        toast.error(getV3ApiErrorMessage(_err, t("workspace.integrations.webhooks.webhook_duplicated_error")));
      },
    });
  };

  return (
    <div className="mt-2 grid h-auto grid-cols-12 content-center rounded-lg py-2 hover:bg-slate-100">
      <div className="col-span-2 flex items-center truncate pl-6 text-sm">
        <div className="flex items-center">
          <div className="text-left">
            {webhook.name ? (
              <div className="text-left">
                <div className="font-medium text-slate-900">{webhook.name}</div>
                <div className="text-xs text-slate-400">{webhook.url}</div>
              </div>
            ) : (
              <div className="font-medium text-slate-900">{webhook.url}</div>
            )}
          </div>
        </div>
      </div>
      <div className="col-span-1 my-auto text-center text-sm text-slate-800">
        <Badge type="gray" size="tiny" text={webhook.source || t("common.user")} className="capitalize" />
      </div>
      <div className="col-span-3 my-auto flex min-w-0 items-center justify-center gap-x-2 text-sm text-slate-800">
        {renderSelectedSurveysText(webhook, surveys)}
        {hasRestrictedAttachedSurvey(surveyVisibilityEnabled, webhook.surveyIds, surveys) && (
          <RestrictedSurveyHint kind="paused" />
        )}
      </div>
      <div className="col-span-2 my-auto text-center text-sm text-slate-800">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className="col-span-2 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        <div className="text-slate-400 text-xs">{t("common.created")}</div>
        <div>{timeSince(webhook.createdAt.toString(), locale)}</div>
      </div>
      <div className="col-span-2 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        <div className="text-slate-400 text-xs">{t("common.updated")}</div>
        <div>{timeSince(webhook.updatedAt.toString(), locale)}</div>
      </div>
      <div className="my-auto flex items-center justify-center">
        <Button
          size="sm"
          variant="secondary"
          loading={isPending}
          onClick={handleDuplicate}
          disabled={isPending}
          title={t("workspace.integrations.webhooks.duplicate_webhook")}>
          <CopyIcon className="size-4" />
        </Button>
      </div>
    </div>
  );
};
